circuitLesson({
 id:'u1-l7',unit:1,order:7,pages:'17–20',
 title:'مخطط البوابات المنطقية (FBD): البوابات الأساسية ومثالان',
 summary:'بوابات AND و OR و NOT وما تكافئه من توصيل المفاتيح، ثم تحويل الشكلين (5-2) و (6-2) من مخطط مسار التيار إلى FBD.',
 stations:[
  {intro:true},

  {st:1,short:'مخطط البوابات',title:'مخطط البوابات المنطقية: اسمان لطريقة واحدة',ref:'ص 17',
   q:'رأيت في المخطط السلمي مفاتيح وملفات… فهل يمكن أن نكتب البرنامج نفسه بصناديق صغيرة بدل المفاتيح؟',
   art:String.raw`<svg viewBox="0 0 360 320" role="img" aria-label="بوابة منطقية واحدة، واسمها CSF في Step5 و FBD في Step7" style="font-family:var(--font)" xmlns="http://www.w3.org/2000/svg"><circle cx="180" cy="160" r="140" fill="#FBE6C4"/><g data-tip="بوابة منطقية: صندوق يأخذ المداخل من اليسار ويعطي خرجاً واحداً من اليمين. الرمز داخل الصندوق يحدد نوعها."><rect x="140" y="52" width="80" height="92" rx="4" fill="#FBF6EE" stroke="#2C4A40" stroke-width="3"/><text x="180" y="74" text-anchor="middle" font-size="17" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">&amp;</text></g><g><rect x="72" y="71.66666666666667" width="68" height="22" fill="transparent"/><path d="M106 82.66666666666667H140" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/></g><g><rect x="72" y="102.33333333333334" width="68" height="22" fill="transparent"/><path d="M106 113.33333333333334H140" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/></g><g data-tip="خرج البوابة: النتيجة التي تُرسل إلى الحمل."><rect x="220" y="87.0" width="74" height="22" fill="transparent"/><path d="M220 98.0H254" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/></g><text x="116" y="62" text-anchor="middle" font-size="13" fill="#2C4A40" font-weight="600">المداخل</text><text x="254" y="84" text-anchor="middle" font-size="13" fill="#2C4A40" font-weight="600">الخرج</text><g data-tip="في برنامج ⟦Step5⟧ تسمى الطريقة ⟦CSF⟧ اختصار ⟦Control System Flowchart⟧."><rect x="70" y="172" width="220" height="40" rx="12" fill="#FBF6EE" stroke="#2C4A40" stroke-width="2.5"/><text x="241.6" y="198" text-anchor="middle" font-size="14" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">Step5</text><text x="180" y="198" text-anchor="middle" font-size="13" fill="#2C4A40" font-weight="500">يسميها</text><text x="114" y="198" text-anchor="middle" font-size="15" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">CSF</text></g><g data-tip="في برنامج ⟦Step7⟧ تسمى الطريقة نفسها ⟦FBD⟧ اختصار ⟦Function Block Diagram⟧."><rect x="70" y="224" width="220" height="40" rx="12" fill="#FBF6EE" stroke="#2C4A40" stroke-width="2.5"/><text x="241.6" y="250" text-anchor="middle" font-size="14" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">Step7</text><text x="180" y="250" text-anchor="middle" font-size="13" fill="#2C4A40" font-weight="500">يسميها</text><text x="114" y="250" text-anchor="middle" font-size="15" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">FBD</text></g><text x="180" y="296" text-anchor="middle" font-size="14" fill="#2C4A40" font-weight="600">اسمان لطريقة واحدة</text></svg>`,
   cap:'البوابة صندوق: المداخل من اليسار والخرج من اليمين.<br><b>مرّر المؤشر على البوابة وعلى البطاقتين (أو المسها في الجوال) لتعرف معناها.</b>',
   side:[
    {book:String.raw`<p>ثانياً: مخطط البوابات المنطقية <span class="ltr">(Control System Flowchart)</span> واختصارها <span class="ltr">(CSF)</span> على برنامج <span class="ltr">(Step5)</span>. أما على برنامج <span class="ltr">(Step7)</span> فتسمى مخطط البوابات المنطقية بـ <span class="ltr">(Function Block Diagram)</span> واختصارها <span class="ltr">(FBD)</span>.</p>
     <p>وهذه الطريقة يتم استخدام البوابات المنطقية في تنفيذ عمليات التحكم. والبوابات الأساسية الثلاث هي المستخدمة. وهي على النحو التالي:</p>`,ref:'ص 17'}
   ],
   body:[
    {tip:String.raw`<p>هذه هي الطريقة الثانية من طرق البرمجة الثلاث. الدائرة هي نفسها، لكن بدل أن نرسم مفاتيح على التوالي والتوازي نرسم <b>بوابات</b>: كل بوابة تأخذ مداخل (المفاتيح) وتعطي خرجاً واحداً. والقاعدة التي سنستعملها دائماً: المفتاح المضغوط يعطي البوابة إشارة <span class="ltr">1</span>، وغير المضغوط يعطي <span class="ltr">0</span>.</p>`,title:'ما الجديد هنا؟'},
    {predict:{q:String.raw`فتحت برنامج <span class="ltr">Step7</span> لتكتب البرنامج بالبوابات. ما اسم هذه الطريقة الذي ستجده فيه؟`,opts:[
     [String.raw`<span class="ltr">CSF</span>`,false,String.raw`هذا اسمها في برنامج <span class="ltr">Step5</span> الأقدم.`],
     [String.raw`<span class="ltr">FBD</span>`,true,String.raw`في <span class="ltr">Step7</span> تسمى <span class="ltr">Function Block Diagram</span> واختصارها <span class="ltr">FBD</span> (ص 17).`],
     [String.raw`<span class="ltr">STL</span>`,false,String.raw`<span class="ltr">STL</span> قائمة الإجراءات، وهي الطريقة الثالثة التي تُكتب فيها أوامر بالحروف.`]]}}
   ]},

  {st:2,short:'بوابة AND',title:'بوابة (و) AND: كل المداخل معاً',ref:'ص 17',
   q:'متى يعمل الحمل إذا كان المفتاحان على التوالي؟ وما البوابة التي تعطي النتيجة نفسها؟',
   art:String.raw`<svg viewBox="0 0 360 320" role="img" aria-label="بوابة AND بمدخلين تكافئ مفتاحين على التوالي" style="font-family:var(--font)" xmlns="http://www.w3.org/2000/svg"><circle cx="180" cy="160" r="140" fill="#F7DCC8"/><g data-tip="بوابة ⟦AND⟧ (و): الرمز ⟦&amp;⟧. الخرج يعمل فقط إذا كانت كل المداخل مضغوطة."><rect x="58" y="96" width="48" height="78" rx="4" fill="#FBF6EE" stroke="#2C4A40" stroke-width="3"/><text x="82" y="118" text-anchor="middle" font-size="17" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">&amp;</text></g><g><rect x="2" y="111.0" width="56" height="22" fill="transparent"/><path d="M36 122.0H58" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/></g><text x="32" y="127" text-anchor="end" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">S1</text><g><rect x="2" y="137.0" width="56" height="22" fill="transparent"/><path d="M36 148.0H58" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/></g><text x="32" y="153" text-anchor="end" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">S2</text><path d="M106 135.0H122" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><text x="126" y="140" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">H1</text><text x="154" y="146" text-anchor="middle" font-size="26" fill="#2C4A40" font-weight="700">=</text><g transform="translate(205.8 32.4) scale(1.150)"><path d="M8 14H110" fill="none" stroke="#2C4A40" stroke-width="3.5" stroke-linecap="round"/><path d="M8 196H110" fill="none" stroke="#2C4A40" stroke-width="3.5" stroke-linecap="round"/><g data-tip="⟦L1⟧: خط الطور — منه يبدأ مسار التيار."><rect x="-22" y="2" width="28" height="24" fill="transparent"/><text x="-8" y="19" text-anchor="middle" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">L1</text></g><g data-tip="⟦N⟧: خط التعادل — إليه يعود التيار بعد الحمل."><rect x="-22" y="184" width="28" height="24" fill="transparent"/><text x="-8" y="201" text-anchor="middle" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">N</text></g><circle cx="40" cy="14" r="4" fill="#2C4A40"/><path d="M40 14V26" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><g data-tip="⟦S1⟧: تلامس مفتوح ⟦N.O⟧ — يوصل التيار عند الضغط فقط."><rect x="20" y="31" width="62" height="42" rx="6" fill="transparent"/><path d="M40 26V42" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 62V78" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 62L27 41" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="62" r="3" fill="#2C4A40"/></g><text x="57" y="57" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">S1</text><g data-tip="⟦S2⟧: تلامس مفتوح ⟦N.O⟧ — يوصل التيار عند الضغط فقط."><rect x="20" y="83" width="62" height="42" rx="6" fill="transparent"/><path d="M40 78V94" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 114V130" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 114L27 93" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="114" r="3" fill="#2C4A40"/></g><text x="57" y="109" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">S2</text><path d="M40 130V142" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><g data-tip="⟦H1⟧: الحمل (مصباح). يضيء إذا وصله التيار عبر S1 و S2 معاً."><path d="M40 142V150" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="163" r="13" fill="#F2C14E" stroke="#2C4A40" stroke-width="3"/><path d="M31 154L49 172M49 154L31 172" stroke="#2C4A40" stroke-width="2.5"/><path d="M40 176V184" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/></g><text x="62" y="168" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">H1</text><path d="M40 184V196" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="196" r="4" fill="#2C4A40"/></g><text x="180" y="306" text-anchor="middle" font-size="14" fill="#2C4A40" font-weight="600" direction="rtl">AND تكافئ التوالي</text></svg>`,
   cap:'بوابة AND بمدخلين (يسار) تعطي ما يعطيه مفتاحان على التوالي (يمين).<br><b>مرّر المؤشر على البوابة والمفاتيح والمصباح (أو المسها في الجوال) لتعرف معناها.</b>',
   side:[
    {book:String.raw`<p>1- بوابة (و) وتسمى <span class="ltr">(AND)</span> ورمزها: <svg viewBox="0 0 96 48" width="96" height="48" role="img" aria-label="رمز بوابة AND" style="vertical-align:middle;display:inline-block" xmlns="http://www.w3.org/2000/svg"><path d="M4 16H30M4 32H30M66 24H92" stroke="#2C4A40" stroke-width="2.5"/><rect x="30" y="4" width="36" height="40" rx="3" fill="#FBF6EE" stroke="#2C4A40" stroke-width="2.5"/><text x="48" y="22" text-anchor="middle" font-size="15" font-weight="700" fill="#2C4A40" font-family="var(--mono)">&amp;</text></svg></p>
     <p>من شروط هذه البوابة أن يكون لها على الأقل دخلان. وهذه البوابة تكافئ توصيل مفتاحين على <b>التوالي</b> إذا كان لها مدخلان، أو ثلاث مفاتيح إذا كان لها ثلاثة مداخل وهكذا. علماً بأن أقصى عدد مداخل لبوابة <span class="ltr">(AND)</span> هو <span class="ltr">(8)</span> مداخل.</p>`,ref:'ص 17'}
   ],
   body:[
    {tip:String.raw`<p>رمزها في الكتاب مستطيل بداخله <b class="ltr">&amp;</b>. في التوالي يمر التيار في طريق واحد، فإذا انفتح أي مفتاح انقطع. وكذلك AND: خرجها <span class="ltr">1</span> <b>فقط</b> إذا كانت <b>كل</b> المداخل <span class="ltr">1</span>، ويكفي مدخل واحد قيمته <span class="ltr">0</span> ليصبح الخرج <span class="ltr">0</span>.</p>`,title:'الفكرة في سطر'},
    {add:String.raw`<p>في بعض المكابس الصناعية لا تنزل الضاغطة إلا إذا ضغط العامل زرّين متباعدين <b>بيديه الاثنتين معاً</b>، حتى لا تكون يده تحتها. هذا شرط AND: الزر الأول <b>و</b> الزر الثاني.</p>`,title:'من المصنع'},
    {predict:{q:'بوابة AND لها ثلاثة مداخل: الأول والثاني مضغوطان، والثالث غير مضغوط. هل يعمل الخرج؟',opts:[
     ['لا يعمل',true,'AND تحتاج كل المداخل؛ مدخل واحد غير مضغوط يقطع الخرج كما يقطع مفتاح مفتوح دائرة التوالي.'],
     ['يعمل، لأن أغلب المداخل مضغوطة',false,'لا يوجد «أغلبية» في AND؛ هذا يشبه ثلاثة مفاتيح على التوالي أحدها مفتوح.'],
     ['يعمل لأن المدخل الأول مضغوط',false,'هذا سلوك OR وليس AND.']]}},
    {watch:String.raw`<p>بوابة AND لا تكون بمدخل واحد: «على الأقل دخلان». وأقصى عدد مداخل لها في الكتاب <span class="ltr">8</span>.</p>`}
   ]},

  {st:3,short:'بوابة OR',title:'بوابة (أو) OR: يكفي مدخل واحد',ref:'ص 17',
   q:'إذا كان لدينا ضاغطان على التوازي، فهل نحتاج أن نضغطهما معاً؟',
   art:String.raw`<svg viewBox="0 0 360 320" role="img" aria-label="بوابة OR بمدخلين تكافئ مفتاحين على التوازي" style="font-family:var(--font)" xmlns="http://www.w3.org/2000/svg"><circle cx="180" cy="160" r="140" fill="#DDEFE6"/><g data-tip="بوابة ⟦OR⟧ (أو): الرمز ⟦&gt;=1⟧ ومعناه «واحد أو أكثر». يكفي أن يكون أحد المداخل مضغوطاً."><rect x="58" y="96" width="48" height="78" rx="4" fill="#FBF6EE" stroke="#2C4A40" stroke-width="3"/><text x="82" y="118" text-anchor="middle" font-size="17" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">&gt;=1</text></g><g><rect x="2" y="111.0" width="56" height="22" fill="transparent"/><path d="M36 122.0H58" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/></g><text x="32" y="127" text-anchor="end" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">S1</text><g><rect x="2" y="137.0" width="56" height="22" fill="transparent"/><path d="M36 148.0H58" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/></g><text x="32" y="153" text-anchor="end" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">S2</text><path d="M106 135.0H122" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><text x="126" y="140" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">H1</text><text x="154" y="146" text-anchor="middle" font-size="26" fill="#2C4A40" font-weight="700">=</text><g transform="translate(184.3 82.9) scale(0.924)"><path d="M8 14H180" fill="none" stroke="#2C4A40" stroke-width="3.5" stroke-linecap="round"/><path d="M8 144H180" fill="none" stroke="#2C4A40" stroke-width="3.5" stroke-linecap="round"/><g data-tip="⟦L1⟧: خط الطور — منه يبدأ مسار التيار."><rect x="-22" y="2" width="28" height="24" fill="transparent"/><text x="-8" y="19" text-anchor="middle" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">L1</text></g><g data-tip="⟦N⟧: خط التعادل — إليه يعود التيار بعد الحمل."><rect x="-22" y="132" width="28" height="24" fill="transparent"/><text x="-8" y="149" text-anchor="middle" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">N</text></g><circle cx="40" cy="14" r="4" fill="#2C4A40"/><path d="M40 14V26" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><g data-tip="⟦S1⟧: تلامس مفتوح ⟦N.O⟧ — يوصل التيار عند الضغط فقط."><rect x="20" y="31" width="62" height="42" rx="6" fill="transparent"/><path d="M40 26V42" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 62V78" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 62L27 41" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="62" r="3" fill="#2C4A40"/></g><text x="57" y="57" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">S1</text><g data-tip="⟦S2⟧: تلامس مفتوح ⟦N.O⟧ — يوصل التيار عند الضغط فقط."><rect x="90" y="31" width="62" height="42" rx="6" fill="transparent"/><path d="M110 26V42" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M110 62V78" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M110 62L97 41" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="110" cy="62" r="3" fill="#2C4A40"/></g><text x="127" y="57" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">S2</text><path d="M40 26H110" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 78H110" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="26" r="4" fill="#2C4A40"/><circle cx="40" cy="78" r="4" fill="#2C4A40"/><circle cx="110" cy="26" r="4" fill="#2C4A40"/><circle cx="110" cy="78" r="4" fill="#2C4A40"/><path d="M40 78V90" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><g data-tip="⟦H1⟧: الحمل (مصباح). يكفي أن يصله التيار من أحد الفرعين."><path d="M40 90V98" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="111" r="13" fill="#F2C14E" stroke="#2C4A40" stroke-width="3"/><path d="M31 102L49 120M49 102L31 120" stroke="#2C4A40" stroke-width="2.5"/><path d="M40 124V132" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/></g><text x="62" y="116" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">H1</text><path d="M40 132V144" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="144" r="4" fill="#2C4A40"/></g><text x="180" y="306" text-anchor="middle" font-size="14" fill="#2C4A40" font-weight="600" direction="rtl">OR تكافئ التوازي</text></svg>`,
   cap:'بوابة OR بمدخلين (يسار) تعطي ما يعطيه مفتاحان على التوازي (يمين).<br><b>مرّر المؤشر على البوابة والمفاتيح والمصباح (أو المسها في الجوال) لتعرف معناها.</b>',
   side:[
    {book:String.raw`<p>2- بوابة (أو) وتسمى <span class="ltr">(OR)</span> ورمزها: <svg viewBox="0 0 96 48" width="96" height="48" role="img" aria-label="رمز بوابة OR" style="vertical-align:middle;display:inline-block" xmlns="http://www.w3.org/2000/svg"><path d="M4 16H30M4 32H30M66 24H92" stroke="#2C4A40" stroke-width="2.5"/><rect x="30" y="4" width="36" height="40" rx="3" fill="#FBF6EE" stroke="#2C4A40" stroke-width="2.5"/><text x="48" y="21" text-anchor="middle" font-size="12" font-weight="700" fill="#2C4A40" font-family="var(--mono)" direction="ltr">&gt;=1</text></svg></p>
     <p>من شروط هذه البوابة أن يكون لها على الأقل مدخلان. وهذه البوابة تكافئ توصيل مفتاحين على <b>التوازي</b> إذا كان لها مدخلان، أو ثلاثة مفاتيح إذا كان لها ثلاثة مداخل وهكذا. علماً بأن أقصى عدد مداخل لبوابة <span class="ltr">(OR)</span> هو <span class="ltr">(8)</span> مداخل.</p>`,ref:'ص 17'}
   ],
   body:[
    {tip:String.raw`<p>الرمز <b class="ltr">&gt;=1</b> يُقرأ «واحد أو أكثر»: يكفي أن يكون مدخل واحد على الأقل <span class="ltr">1</span> ليصبح الخرج <span class="ltr">1</span>، تماماً كالتوازي: التيار يجد طريقاً من أي فرع مغلق.</p>`,title:'كيف تقرأ الرمز؟'},
    {add:String.raw`<p>إضاءة ممر طويل لها ضاغط عند كل باب: يكفي أن تضغط أيّاً منها لتضيء. هذا شرط OR.</p>`,title:'من الواقع'},
    {predict:{q:'أيّ توصيل يكافئ بوابة OR لها مدخلان؟',opts:[
     ['مفتاحان على التوالي',false,'التوالي يكافئ AND.'],
     ['مفتاح مغلق N.C',false,'المفتاح المغلق يكافئ NOT (المحطة القادمة).'],
     ['مفتاحان على التوازي',true,'«تكافئ توصيل مفتاحين على التوازي إذا كان لها مدخلان» (ص 17).']]}}
   ]},

  {st:4,short:'بوابة NOT',title:'بوابة (لا) NOT: الدائرة الصغيرة تعكس',ref:'ص 17',
   q:'ضاغط الفصل يجب أن يقطع عندما نضغطه… فكيف نكتبه في البوابات؟',
   art:String.raw`<svg viewBox="0 0 360 320" role="img" aria-label="رمز NOT خط ينتهي بدائرة صغيرة ويكافئ تلامساً مغلقاً N.C" style="font-family:var(--font)" xmlns="http://www.w3.org/2000/svg"><circle cx="180" cy="160" r="140" fill="#E6E2F8"/><g data-tip="رمز ⟦NOT⟧ (لا): خط ينتهي بدائرة صغيرة. الدائرة الصغيرة تعكس الإشارة: الخرج عكس الدخل دائماً."><rect x="28" y="128" width="130" height="34" fill="transparent"/><path d="M36 145H124" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="131" cy="145" r="7" fill="#FBF6EE" stroke="#2C4A40" stroke-width="3"/><path d="M138 145H150" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/></g><text x="36" y="128" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">S0</text><text x="80" y="186" text-anchor="middle" font-size="12" fill="#2C4A40" font-weight="600">دخل واحد</text><text x="80" y="204" text-anchor="middle" font-size="12" fill="#2C4A40" font-weight="600">والخرج عكسه</text><text x="178" y="152" text-anchor="middle" font-size="30" fill="#2C4A40" font-weight="700">=</text><g transform="translate(223.6 76.4) scale(1.071)"><path d="M8 14H110" fill="none" stroke="#2C4A40" stroke-width="3.5" stroke-linecap="round"/><path d="M8 144H110" fill="none" stroke="#2C4A40" stroke-width="3.5" stroke-linecap="round"/><g data-tip="⟦L1⟧: خط الطور — منه يبدأ مسار التيار."><rect x="-22" y="2" width="28" height="24" fill="transparent"/><text x="-8" y="19" text-anchor="middle" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">L1</text></g><g data-tip="⟦N⟧: خط التعادل — إليه يعود التيار بعد الحمل."><rect x="-22" y="132" width="28" height="24" fill="transparent"/><text x="-8" y="149" text-anchor="middle" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">N</text></g><circle cx="40" cy="14" r="4" fill="#2C4A40"/><path d="M40 14V26" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><g data-tip="⟦S0⟧: تلامس مغلق ⟦N.C⟧ — يمرّر التيار وهو غير مضغوط، ويقطعه عند الضغط."><rect x="20" y="31" width="62" height="42" rx="6" fill="transparent"/><path d="M40 26V42" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 62V78" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 42H50" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 62L53 38" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="62" r="3" fill="#2C4A40"/></g><text x="57" y="57" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">S0</text><path d="M40 78V90" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><g data-tip="⟦H1⟧: الحمل. يعمل ما دام S0 غير مضغوط."><path d="M40 90V98" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="111" r="13" fill="#F2C14E" stroke="#2C4A40" stroke-width="3"/><path d="M31 102L49 120M49 102L31 120" stroke="#2C4A40" stroke-width="2.5"/><path d="M40 124V132" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/></g><text x="62" y="116" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">H1</text><path d="M40 132V144" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="144" r="4" fill="#2C4A40"/></g><text x="180" y="306" text-anchor="middle" font-size="14" fill="#2C4A40" font-weight="600" direction="rtl">NOT تمثل مفتاحاً مغلقاً N.C</text></svg>`,
   cap:'رمز NOT: خط ينتهي بدائرة صغيرة، ويكافئ تلامساً مغلقاً.<br><b>مرّر المؤشر على الرمز والمفتاح (أو المسهما في الجوال) لتعرف معناهما.</b>',
   side:[
    {book:String.raw`<p>3- بوابة (لا) وتسمى <span class="ltr">(NOT)</span> ورمزها: <svg viewBox="0 0 96 48" width="96" height="48" role="img" aria-label="رمز NOT" style="vertical-align:middle;display:inline-block" xmlns="http://www.w3.org/2000/svg"><path d="M8 24H70" stroke="#2C4A40" stroke-width="2.5"/><circle cx="76" cy="24" r="6" fill="#FBF6EE" stroke="#2C4A40" stroke-width="2.5"/></svg></p>
     <p>من شروط هذه البوابة أن لها دخلاً واحداً والخرج يكون عكس الدخل دائماً. وهي تمثل مفتاحاً مغلقاً <span class="ltr">(N.C)</span>.</p>`,ref:'ص 17'}
   ],
   body:[
    {tip:String.raw`<p>رمزها خط ينتهي بدائرة صغيرة. وفي رسوم الكتاب لا تظهر NOT صندوقاً مستقلاً، بل <b>دائرة صغيرة على مدخل البوابة</b>. فإذا رأيت مدخلاً عليه دائرة صغيرة فاقرأه: «هذا المفتاح <b>غير</b> مضغوط».</p>`,title:'أين ستراها؟'},
    {watch:String.raw`<p>في دوائر الوحدة يصل للـ PLC إشارة <span class="ltr">1</span> عند الضغط على <b>أي</b> ضاغط، حتى ضاغط الفصل. لذلك يُكتب ضاغط الفصل في البرنامج بالدائرة الصغيرة (NOT): غير مضغوط ← يصل <span class="ltr">0</span> ← تعكسه إلى <span class="ltr">1</span> فيمر الشرط، ومضغوط ← <span class="ltr">1</span> ← يصير <span class="ltr">0</span> فيقطع.</p>`},
    {predict:{q:'ضاغط الفصل S0 يدخل البوابة بدائرة صغيرة. ماذا يصل إلى البوابة وهو غير مضغوط؟',opts:[
     [String.raw`<span class="ltr">0</span>، لأنه غير مضغوط`,false,'هذه قيمته قبل الدائرة الصغيرة؛ الدائرة تعكسها.'],
     [String.raw`<span class="ltr">1</span>، لأن الدائرة الصغيرة تعكس <span class="ltr">0</span> إلى <span class="ltr">1</span>`,true,'لذلك لا يمنع التشغيل ما دام غير مضغوط، كالتلامس المغلق تماماً.'],
     ['لا يصل شيء حتى يُضغط',false,'المدخل له دائماً قيمة: 0 أو 1.']]}},
    {title:'جرّب البوابات الثلاث بمفاتيح مثال 1',widget:(el,B)=>{
      const N={'I0.0':'S0','I0.1':'S1','I0.2':'S2','Q4.5':'H1'},AD={S0:'I0.0',S1:'I0.1',S2:'I0.2'};
      const G={and:{t:'AND (و)',stl:['A I 0.1','A I 0.2','= Q 4.5'],ins:['S1','S2'],tree:{s:[L_('S1'),L_('S2')]},r:'AND: الخرج يعمل فقط إذا ضُغط S1 <b>و</b> S2 معاً — مفتاحان على التوالي.'},
               or:{t:'OR (أو)',stl:['O I 0.1','O I 0.2','= Q 4.5'],ins:['S1','S2'],tree:{p:[L_('S1'),L_('S2')]},r:'OR: يكفي أن تضغط S1 <b>أو</b> S2 — مفتاحان على التوازي.'},
               not:{t:'NOT (لا)',stl:['AN I 0.0','= Q 4.5'],ins:['S0'],tree:{s:[L_('S0',1)]},r:'NOT: الخرج عكس الدخل — يعمل ما دام S0 <b>غير</b> مضغوط، كالتلامس المغلق N.C.'}};
      let g='and';const v={S0:0,S1:0,S2:0};
      const draw=()=>{const c=G[g],P=B.createPLC([{stl:c.stl}]);c.ins.forEach(k=>P.set(AD[k],v[k]));P.scan(0.05);const on=P.get('Q4.5');
        el.innerHTML=`<div class="w-row" style="margin-top:0"><span class="mseg">${Object.keys(G).map(k=>`<button type="button" data-g="${k}" aria-pressed="${k===g}">${G[k].t}</button>`).join('')}</span></div>
         <div class="w-row">${c.ins.map(k=>`<button class="sw" type="button" data-i="${k}" aria-pressed="${!!v[k]}"><span class="knob"></span><b>${k}</b><small>${v[k]?'مضغوط = 1':'غير مضغوط = 0'}</small></button>`).join('')}</div>
         <p class="sub" style="margin-top:10px">البوابة (FBD)</p><div class="svgbox" style="max-width:560px">${B.fbdNetwork(P.nets[0],P,N)}</div>
         <p class="sub" style="margin-top:10px">ما تكافئه في مخطط مسار التيار</p>${hwBox(c.tree,x=>v[x],{l:'H1',kind:'lamp'},1)}
         <p class="sub" style="margin-top:8px">المصباح H1 الآن: <b>${on?'يضيء (الخرج 1)':'منطفئ (الخرج 0)'}</b>. ${c.r}</p>
         <p class="sub">العناوين من جدول ترميز مثال 1 (ص 18): <span class="ltr">S0 = I0.0</span>، <span class="ltr">S1 = I0.1</span>، <span class="ltr">S2 = I0.2</span>، <span class="ltr">H1 = Q4.5</span>.</p>`;
        el.querySelectorAll('[data-g]').forEach(b=>b.onclick=()=>{g=b.dataset.g;draw()});
        el.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>{v[b.dataset.i]^=1;draw()})};
      draw();
    }}
   ]},

  {st:5,short:'مثال 1',title:'مثال 1: تشغيل من مكانين والفصل من مكان واحد',ref:'ص 18–19',
   q:'هذه الدائرة نفسها كتبناها من قبل بالمخطط السلمي. كيف تتحول إلى بوابات؟',
   art:String.raw`<svg viewBox="0 0 360 320" role="img" aria-label="مخطط مسار التيار للشكل 5-2: S0 مغلق ثم S1 و S2 على التوازي ثم H1" style="font-family:var(--font)" xmlns="http://www.w3.org/2000/svg"><circle cx="180" cy="160" r="140" fill="#FBE6C4"/><g transform="translate(89.6 30.4) scale(1.150)"><path d="M8 14H180" fill="none" stroke="#2C4A40" stroke-width="3.5" stroke-linecap="round"/><path d="M8 196H180" fill="none" stroke="#2C4A40" stroke-width="3.5" stroke-linecap="round"/><g data-tip="⟦L1⟧: خط الطور — منه يبدأ مسار التيار."><rect x="-22" y="2" width="28" height="24" fill="transparent"/><text x="-8" y="19" text-anchor="middle" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">L1</text></g><g data-tip="⟦N⟧: خط التعادل — إليه يعود التيار بعد الحمل."><rect x="-22" y="184" width="28" height="24" fill="transparent"/><text x="-8" y="201" text-anchor="middle" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">N</text></g><circle cx="40" cy="14" r="4" fill="#2C4A40"/><path d="M40 14V26" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><g data-tip="⟦S0⟧: ضاغط الفصل، تلامس مغلق ⟦N.C⟧ — العنوان ⟦I 0.0⟧."><rect x="20" y="31" width="62" height="42" rx="6" fill="transparent"/><path d="M40 26V42" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 62V78" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 42H50" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 62L53 38" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="62" r="3" fill="#2C4A40"/></g><text x="57" y="57" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">S0</text><g data-tip="⟦S1⟧: ضاغط التشغيل الأول ⟦N.O⟧ — العنوان ⟦I 0.1⟧."><rect x="20" y="83" width="62" height="42" rx="6" fill="transparent"/><path d="M40 78V94" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 114V130" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 114L27 93" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="114" r="3" fill="#2C4A40"/></g><text x="57" y="109" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">S1</text><g data-tip="⟦S2⟧: ضاغط التشغيل الثاني ⟦N.O⟧ — العنوان ⟦I 0.2⟧."><rect x="90" y="83" width="62" height="42" rx="6" fill="transparent"/><path d="M110 78V94" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M110 114V130" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M110 114L97 93" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="110" cy="114" r="3" fill="#2C4A40"/></g><text x="127" y="109" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">S2</text><path d="M40 78H110" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 130H110" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="78" r="4" fill="#2C4A40"/><circle cx="40" cy="130" r="4" fill="#2C4A40"/><circle cx="110" cy="78" r="4" fill="#2C4A40"/><circle cx="110" cy="130" r="4" fill="#2C4A40"/><path d="M40 130V142" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><g data-tip="⟦H1⟧: مجموعة الإضاءة (الحمل) — العنوان ⟦Q 4.5⟧."><path d="M40 142V150" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="163" r="13" fill="#F2C14E" stroke="#2C4A40" stroke-width="3"/><path d="M31 154L49 172M49 154L31 172" stroke="#2C4A40" stroke-width="2.5"/><path d="M40 176V184" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/></g><text x="62" y="168" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">H1</text><path d="M40 184V196" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="196" r="4" fill="#2C4A40"/></g><text x="180" y="308" text-anchor="middle" font-size="14" fill="#2C4A40" font-weight="600" direction="rtl">الشكل ⁦(5-2)⁩</text></svg>`,
   cap:'الشكل <span class="ltr">(5-2)</span>: ضاغط فصل مغلق، ثم ضاغطا تشغيل على التوازي، ثم مجموعة الإضاءة.<br><b>مرّر المؤشر على أي مفتاح أو على المصباح (أو المسه في الجوال) لتعرف دوره وعنوانه.</b>',
   side:[
    {book:String.raw`<p>الشكل (5-2) يمثل مخطط مسار التيار لدائرة تشغيل مجموعة أحمال من مكانين مختلفين والفصل من مكان واحد. والمطلوب: تحويل الدائرة التالية من مخطط مسار التيار إلى دائرة <span class="ltr">(FBD)</span>.</p>`,ref:'ص 18'},
    {predict:{q:'عند تحويل الدائرة: بأي ترتيب تظهر البوابات؟',opts:[
     ['بوابة OR تجمع S1 و S2، ثم بوابة AND مع S0 بدائرة صغيرة',true,'التوازي (S1 أو S2) يصبح OR، ثم يأتي بالتوالي مع S0 المغلق فتجمعهما AND.'],
     ['بوابة AND تجمع S1 و S2، ثم OR مع S0',false,'S1 و S2 على التوازي وليسا على التوالي، فهما OR.'],
     ['بوابة NOT وحدها على S0',false,'NOT وحدها لا تكفي؛ أين ذهب S1 و S2؟']]}}
   ],
   body:[
    {book:String.raw`<p><b>الدراسة:</b></p><p>1- من الشكل (5-2) المبين يتم تشغيل الحمل (مجموعة إضاءة <span class="ltr">H1</span>) بالضغط على الضاغط (<span class="ltr">S1</span> أو <span class="ltr">S2</span>) والفصل بالضغط على (<span class="ltr">S0</span>).</p><p>2- الترميز:</p>`+bookTable([['S0','I0.0'],['S1','I0.1'],['S2','I0.2'],['H1','Q4.5']])+String.raw`<p>3- الرسم: مخطط البوابات المنطقية <span class="ltr">(FBD)</span></p>`+progFig(C.F1.program,'fbd',C.F1.io),ref:'ص 18–19'},
    {tip:String.raw`<ol><li>ابحث عن المفاتيح <b>المتوازية</b> (<span class="ltr">S1</span> و <span class="ltr">S2</span>) ← بوابة <b>OR</b>.</li><li>ما بعدها <b>على التوالي</b> مع <span class="ltr">S0</span> ← بوابة <b>AND</b> تأخذ خرج OR و <span class="ltr">S0</span>.</li><li><span class="ltr">S0</span> ضاغط فصل مغلق ← يدخل بـ<b>دائرة صغيرة</b>.</li><li>خرج AND ← المخرج <span class="ltr">Q4.5</span> (المصباح <span class="ltr">H1</span>).</li></ol>`,title:'كيف تحوّل الدائرة خطوة خطوة'},
    {predict:{q:'ضغطت S1 و S0 معاً. ماذا يحدث للمصباح H1؟',opts:[
     ['يضيء، لأن S1 مضغوط',false,'خرج OR صار 1، لكن AND تحتاج أيضاً مدخل S0 المعكوس.'],
     ['يضيء نصف إضاءة',false,'الخرج في البوابات إما 1 أو 0 فقط.'],
     ['ينطفئ: S0 المضغوط يصبح 0 بعد الدائرة الصغيرة فتقطع AND',true,'الفصل يتغلب على التشغيل، كما في الدائرة الكهربائية تماماً.']]}}
   ]},

  {st:6,short:'مثال 2',title:'مثال 2: متمم له شروط خاصة',ref:'ص 19–20',
   q:'فرعان متوازيان، وفي أحدهما تلامس مغلق موازٍ لتلامس مفتوح… كيف نحوّل هذا إلى بوابات؟',
   art:String.raw`<svg viewBox="0 0 360 320" role="img" aria-label="مخطط مسار التيار للشكل 6-2: فرع S1 و S2، وفرع S3 مغلق موازٍ لـ S5 ثم S4، ثم S6 مغلق ثم K10" style="font-family:var(--font)" xmlns="http://www.w3.org/2000/svg"><circle cx="180" cy="160" r="140" fill="#F7DCC8"/><g transform="translate(54.0 7.4) scale(1.089)"><path d="M8 14H250" fill="none" stroke="#2C4A40" stroke-width="3.5" stroke-linecap="round"/><path d="M8 248H250" fill="none" stroke="#2C4A40" stroke-width="3.5" stroke-linecap="round"/><g data-tip="⟦L1⟧: خط الطور — منه يبدأ مسار التيار."><rect x="-22" y="2" width="28" height="24" fill="transparent"/><text x="-8" y="19" text-anchor="middle" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">L1</text></g><g data-tip="⟦N⟧: خط التعادل — إليه يعود التيار بعد الحمل."><rect x="-22" y="236" width="28" height="24" fill="transparent"/><text x="-8" y="253" text-anchor="middle" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">N</text></g><circle cx="40" cy="14" r="4" fill="#2C4A40"/><path d="M40 14V26" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><g data-tip="⟦S1⟧: تلامس مفتوح ⟦N.O⟧ — يوصل التيار عند الضغط فقط."><rect x="20" y="31" width="62" height="42" rx="6" fill="transparent"/><path d="M40 26V42" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 62V78" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 62L27 41" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="62" r="3" fill="#2C4A40"/></g><text x="57" y="57" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">S1</text><g data-tip="⟦S2⟧: تلامس مفتوح ⟦N.O⟧ — يوصل التيار عند الضغط فقط."><rect x="20" y="83" width="62" height="42" rx="6" fill="transparent"/><path d="M40 78V94" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 114V130" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 114L27 93" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="114" r="3" fill="#2C4A40"/></g><text x="57" y="109" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">S2</text><g data-tip="⟦S3⟧: تلامس مغلق ⟦N.C⟧ موازٍ لـ ⟦S5⟧ — يمرّر وهو غير مضغوط."><rect x="90" y="31" width="62" height="42" rx="6" fill="transparent"/><path d="M110 26V42" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M110 62V78" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M110 42H120" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M110 62L123 38" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="110" cy="62" r="3" fill="#2C4A40"/></g><text x="127" y="57" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">S3</text><g data-tip="⟦S5⟧: تلامس مفتوح ⟦N.O⟧ — يوصل التيار عند الضغط فقط."><rect x="160" y="31" width="62" height="42" rx="6" fill="transparent"/><path d="M180 26V42" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M180 62V78" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M180 62L167 41" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="180" cy="62" r="3" fill="#2C4A40"/></g><text x="197" y="57" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">S5</text><path d="M110 26H180" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M110 78H180" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="110" cy="26" r="4" fill="#2C4A40"/><circle cx="110" cy="78" r="4" fill="#2C4A40"/><circle cx="180" cy="26" r="4" fill="#2C4A40"/><circle cx="180" cy="78" r="4" fill="#2C4A40"/><g data-tip="⟦S4⟧: تلامس مفتوح ⟦N.O⟧ — يوصل التيار عند الضغط فقط."><rect x="90" y="83" width="62" height="42" rx="6" fill="transparent"/><path d="M110 78V94" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M110 114V130" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M110 114L97 93" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="110" cy="114" r="3" fill="#2C4A40"/></g><text x="127" y="109" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">S4</text><path d="M40 26H110" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 130H110" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="26" r="4" fill="#2C4A40"/><circle cx="40" cy="130" r="4" fill="#2C4A40"/><circle cx="110" cy="26" r="4" fill="#2C4A40"/><circle cx="110" cy="130" r="4" fill="#2C4A40"/><g data-tip="⟦S6⟧: تلامس مغلق ⟦N.C⟧ — يفصل ⟦K10⟧ مهما كان الفرع الذي يغذيه."><rect x="20" y="135" width="62" height="42" rx="6" fill="transparent"/><path d="M40 130V146" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 166V182" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 146H50" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><path d="M40 166L53 142" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="166" r="3" fill="#2C4A40"/></g><text x="57" y="161" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">S6</text><path d="M40 182V194" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><g data-tip="⟦K10⟧: ملف المتمم (الحمل)."><path d="M40 194V204" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><rect x="23" y="204" width="34" height="22" rx="3" fill="#4FB3A9" stroke="#2C4A40" stroke-width="3"/><path d="M40 226V236" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/></g><text x="62" y="220" text-anchor="start" font-size="13" fill="#2C4A40" font-weight="700" font-family="var(--mono)" direction="ltr">K10</text><path d="M40 236V248" fill="none" stroke="#2C4A40" stroke-width="3" stroke-linecap="round"/><circle cx="40" cy="248" r="4" fill="#2C4A40"/></g><text x="180" y="308" text-anchor="middle" font-size="14" fill="#2C4A40" font-weight="600" direction="rtl">الشكل ⁦(6-2)⁩</text></svg>`,
   cap:'الشكل <span class="ltr">(6-2)</span>: فرع S1 و S2، وفرع (S3 المغلق أو S5) ثم S4، ثم S6 المغلق قبل الملف K10.<br><b>مرّر المؤشر على أي مفتاح أو على الملف (أو المسه في الجوال) لتعرف دوره.</b>',
   side:[
    {book:String.raw`<p>الشكل (6-2) يمثل مخطط مسار التيار لدائرة تشغيل متمم له شروط خاصة كما هو موضح في دائرة مسار التيار. والمطلوب: تحويل دائرة مسار التيار التالية إلى دائرة <span class="ltr">(FBD)</span></p>`,ref:'ص 19'},
    {predict:{q:'ضغطت S4 وحده ولم تلمس أي مفتاح آخر. هل يعمل K10؟',opts:[
     ['لا، لأن S5 غير مضغوط',false,'S5 موازٍ لـ S3، و S3 تلامس مغلق يمرّر وهو غير مضغوط.'],
     ['نعم: S3 المغلق يمرّر، و S4 مضغوط، و S6 غير مضغوط',true,'الفرع الأيمن مكتمل: (S3 أو S5) ثم S4، ثم S6 المغلق.'],
     ['لا، لأن S1 و S2 غير مضغوطين',false,'يكفي أحد الفرعين المتوازيين؛ لا نحتاج الفرع الأيسر.']]}}
   ],
   body:[
    {book:String.raw`<p><b>الحل:</b> مخطط البوابات المنطقية <span class="ltr">(FBD)</span></p>`+progFig(C.F2.program,'fbd',C.F2.io),ref:'ص 20'},
    {tip:String.raw`<ol><li>داخل الفرع الأيمن: <span class="ltr">S3</span> (مغلق) <b>أو</b> <span class="ltr">S5</span> ← بوابة OR، و<span class="ltr">S3</span> يدخلها بدائرة صغيرة.</li><li>خرجها <b>و</b> <span class="ltr">S4</span> ← بوابة AND = الفرع الأيمن.</li><li>الفرع الأيسر: <span class="ltr">S1</span> <b>و</b> <span class="ltr">S2</span> ← بوابة AND.</li><li>الفرعان متوازيان ← بوابة OR تجمعهما.</li><li>ثم <b>و</b> <span class="ltr">S6</span> المغلق (بدائرة صغيرة) ← المخرج <span class="ltr">Q5.2</span> (الملف <span class="ltr">K10</span>).</li></ol>`,title:'ابدأ من الداخل إلى الخارج'},
    {watch:String.raw`<p>الكتاب لم يضع لهذا المثال «دراسة» ولا جدول «ترميز»؛ الحل يستعمل مباشرة العناوين <span class="ltr">I3.1…I3.6</span> والخرج <span class="ltr">Q5.2</span>. ربطنا <span class="ltr">S1</span>…<span class="ltr">S6</span> بـ <span class="ltr">I3.1…I3.6</span> و<span class="ltr">K10</span> بـ <span class="ltr">Q5.2</span> <b>استنتاجاً</b> من الحل، وليس نصاً من الكتاب.</p>`,fix:true},
    {predict:{q:'في حل المثال، أيّ مدخلين يدخلان البوابات بدائرة صغيرة؟',opts:[
     ['S3 و S6',true,'كلاهما تلامس مغلق N.C في الشكل (6-2)، والدائرة الصغيرة تمثل المفتاح المغلق.'],
     ['S1 و S2',false,'S1 و S2 تلامسان مفتوحان يدخلان AND مباشرة.'],
     ['S4 و S5',false,'S4 و S5 تلامسان مفتوحان.']]}}
   ]},

  {recap:[
   String.raw`مخطط البوابات اسمه <span class="ltr">CSF</span> في <span class="ltr">Step5</span> و<span class="ltr">FBD</span> في <span class="ltr">Step7</span>، ويستعمل ثلاث بوابات أساسية (ص 17).`,
   String.raw`بوابة AND (الرمز <b class="ltr">&amp;</b>) = مفاتيح على <b>التوالي</b>: الخرج يعمل إذا عملت كل المداخل. على الأقل مدخلان، وأقصى عدد <span class="ltr">8</span>.`,
   String.raw`بوابة OR (الرمز <b class="ltr">&gt;=1</b>) = مفاتيح على <b>التوازي</b>: يكفي مدخل واحد. على الأقل مدخلان، وأقصى عدد <span class="ltr">8</span>.`,
   String.raw`بوابة NOT (الدائرة الصغيرة) = مفتاح مغلق <span class="ltr">N.C</span>: الخرج عكس الدخل دائماً، ولها دخل واحد.`,
   String.raw`للتحويل: التوازي ← OR، والتوالي ← AND، والمفتاح المغلق ← دائرة صغيرة، كما في مثالي الشكلين (5-2) و(6-2).`]}
 ],
 theory:[
  {h:'ثانياً: مخطط البوابات المنطقية (CSF / FBD)',ref:'ص 17',html:'<p>«مخطط البوابات المنطقية (Control System Flowchart) واختصارها (CSF) على برنامج (Step5). أما على برنامج (Step7) فتسمى مخطط البوابات المنطقية بـ (Function Block Diagram) واختصارها (FBD). وهذه الطريقة يتم استخدام البوابات المنطقية في تنفيذ عمليات التحكم. والبوابات الأساسية الثلاث هي المستخدمة. وهي على النحو التالي:»</p>'},
  {h:'1- بوابة (و) AND',ref:'ص 17',html:'<p>رمزها مستطيل بداخله <b class="ltr">&amp;</b>. «من شروط هذه البوابة أن يكون لها على الأقل دخلان. وهذه البوابة تكافئ توصيل مفتاحين على <b>التوالي</b> إذا كان لها مدخلان، أو ثلاث مفاتيح إذا كان لها ثلاثة مداخل وهكذا. علماً بأن أقصى عدد مداخل لبوابة (AND) هو (8) مداخل.»</p>'},
  {h:'2- بوابة (أو) OR',ref:'ص 17',html:'<p>رمزها مستطيل بداخله <b class="ltr">&gt;=1</b>. «من شروط هذه البوابة أن يكون لها على الأقل مدخلان. وهذه البوابة تكافئ توصيل مفتاحين على <b>التوازي</b> إذا كان لها مدخلان، أو ثلاثة مفاتيح إذا كان لها ثلاثة مداخل وهكذا. علماً بأن أقصى عدد مداخل لبوابة (OR) هو (8) مداخل.»</p>'},
  {h:'3- بوابة (لا) NOT',ref:'ص 17',html:'<p>رمزها خط ينتهي بدائرة صغيرة <b class="ltr">——o</b>. «من شروط هذه البوابة أن لها دخلاً واحداً والخرج يكون عكس الدخل دائماً. وهي تمثل مفتاحاً مغلقاً (N.C).»</p>'},
  {note:AR_NOTE+'جرّب البوابات في الأداة التالية: غيّر المداخل وشاهد الخرج، والدائرة الكهربائية المكافئة (توالي، توازي، مفتاح مغلق)، وجدول الحقيقة الذي يسرد كل الحالات.'},
  {widget:(el,B)=>{let g='and',n=2,v=[0,0,0,0];
    const draw=()=>{const ins=g==='not'?1:n,vals=v.slice(0,ins);const out=g==='and'?vals.every(x=>x):g==='or'?vals.some(x=>x):!vals[0];
      const names=vals.map((_,i)=>'S'+(i+1));const tree=g==='and'?{s:names.map(x=>L_(x))}:g==='or'?{p:names.map(x=>L_(x))}:{s:[L_('S1',1)]};
      const stl=g==='not'?['AN I 0.1','= Q 4.0']:(g==='and'?names.map((x,i)=>'A I 0.'+(i+1)):names.map((x,i)=>'O I 0.'+(i+1))).concat(['= Q 4.0']);
      const P=B.createPLC([{stl}]);vals.forEach((x,i)=>P.set('I0.'+(i+1),x));P.scan(0.05);const nm={};names.forEach((x,i)=>nm['I0.'+(i+1)]=x);nm['Q4.0']='H';
      let tt='';if(ins<=3){const rows=1<<ins;tt=`<div class="tablebox" style="max-width:${120+ins*60}px"><table class="tt"><thead><tr>${names.map(x=>`<th>${x}</th>`).join('')}<th>الخرج</th></tr></thead><tbody>`;
        for(let r=0;r<rows;r++){const bits=names.map((_,i)=>(r>>(ins-1-i))&1);const o=g==='and'?bits.every(x=>x):g==='or'?bits.some(x=>x):!bits[0];const cur=bits.every((b,i)=>b===vals[i]);
          tt+=`<tr style="${cur?'background:var(--blue-soft);font-weight:700':''}">${bits.map(b=>`<td class="mono">${b}</td>`).join('')}<td class="mono">${o?1:0}</td></tr>`}tt+='</tbody></table></div>'}
      el.innerHTML=`<div class="fig"><div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center"><div class="seg" role="group">${[['and','AND (و)'],['or','OR (أو)'],['not','NOT (لا)']].map(([k,t])=>`<button data-g="${k}" aria-pressed="${g===k}">${t}</button>`).join('')}</div>
        ${g!=='not'?`<label>عدد المداخل: <select data-n style="font:inherit;padding:3px;border-radius:8px;border:1px solid var(--line);background:var(--surface);color:var(--fg)">${[2,3,4].map(k=>`<option ${k===n?'selected':''}>${k}</option>`).join('')}</select></label>`:''}</div>
        <div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap">${names.map((x,i)=>`<button class="sw" data-i="${i}" aria-pressed="${!!vals[i]}"><span class="knob"></span><b>${x}</b><small>${vals[i]?'1 مضغوط':'0'}</small></button>`).join('')}</div>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px;align-items:start;margin-top:8px">
         <div style="grid-column:1/-1"><h3 class="sm">البوابة (FBD)</h3><div class="svgbox" style="max-width:560px">${B.fbdNetwork(P.nets[0],P,nm)}</div></div>
         <div><h3 class="sm">ما تكافئه في مخطط مسار التيار</h3>${hwBox(tree,x=>vals[names.indexOf(x)],{l:'H',kind:'lamp'},1.1)}</div>
         <div><h3 class="sm">جدول الحقيقة</h3>${tt||'<p class="sub">جدول 4 مداخل فيه 16 سطراً؛ اختر مدخلين أو ثلاثة لعرضه.</p>'}</div></div>
        <p class="sub">الخرج الآن = <b>${out?1:0}</b>. ${g==='and'?'AND: الخرج 1 فقط إذا كانت كل المداخل 1 (مفاتيح على التوالي). أقصى عدد مداخل في الكتاب 8.':g==='or'?'OR: الخرج 1 إذا كان أي مدخل 1 (مفاتيح على التوازي). أقصى عدد مداخل في الكتاب 8.':'NOT: الخرج عكس الدخل دائماً، مثل المفتاح المغلق N.C.'}</p></div>`;
      el.querySelectorAll('[data-g]').forEach(b=>b.onclick=()=>{g=b.dataset.g;draw()});const s=el.querySelector('[data-n]');if(s)s.onchange=e=>{n=+e.target.value;draw()};
      el.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>{v[+b.dataset.i]^=1;draw()})};draw()}},
  {h:'مثال 1',ref:'ص 18–19',html:'<p>«الشكل (5-2) يمثل مخطط مسار التيار لدائرة تشغيل مجموعة أحمال من مكانين مختلفين والفصل من مكان واحد. والمطلوب: تحويل الدائرة التالية من مخطط مسار التيار إلى دائرة (FBD).»</p>'},
  {fig:'(5-2)',ref:'ص 18',caption:'مخطط مسار التيار (نفس دائرة الشكل 3-2)',draw:()=>hwBox(TREE.ex2,()=>0,C.ex2.coil,1.35)},
  {html:'<div class="callout err fixnote"><b>ملاحظة على الكتاب:</b> '+'ترقيم الأشكال في الفصل الثاني يقفز من (3-2) إلى (5-2)؛ لا يوجد في الكتاب شكل (4-2).'+'</div>'},
  {html:'<p><b>1- الدراسة (ص 18):</b> «من الشكل (5-2) المبين يتم تشغيل الحمل (مجموعة إضاءة H1) بالضغط على الضاغط (S1 أو S2) والفصل بالضغط على (S0).»</p><p><b>2- الترميز:</b></p>'+bookTable([['S0','I0.0'],['S1','I0.1'],['S2','I0.2'],['H1','Q4.5']])+'<p><b>3- الرسم (ص 19):</b> بوابة OR تجمع I0.1 و I0.2، وخرجها يدخل بوابة AND مع I0.0 معكوساً (بالدائرة الصغيرة)، وخرج AND هو Q4.5.</p>'},
  {fig:'',ref:'ص 19',caption:'مخطط البوابات المنطقية (FBD) لمثال 1',draw:()=>progFig(C.F1.program,'fbd',C.F1.io)},
  {h:'مثال 2',ref:'ص 19–20',html:'<p>«الشكل (6-2) يمثل مخطط مسار التيار لدائرة تشغيل متمم له شروط خاصة كما هو موضح في دائرة مسار التيار. والمطلوب: تحويل دائرة مسار التيار التالية إلى دائرة (FBD).»</p>'},
  {fig:'(6-2)',ref:'ص 19',caption:'مخطط مسار التيار: فرعان متوازيان [S1 ← S2] ∥ [(S3 مغلق ∥ S5) ← S4]، ثم S6 مغلق ← K10',draw:()=>hwBox(TREE.F2,()=>0,C.F2.coil,1.25)},
  {html:'<div class="callout err fixnote"><b>ملاحظة على الكتاب:</b> '+'لا توجد في الكتاب «دراسة» ولا جدول «ترميز» لمثال 2؛ الحل (ص 20) يستعمل مباشرة العناوين I3.1…I3.6 والخرج Q5.2. الجدول التالي <b>مستنتج</b> من الحل (Sn ↔ I3.n، و K10 ↔ Q5.2) وليس منصوصاً في الكتاب.'+'</div>'},
  {html:bookTable([['S1','I3.1'],['S2','I3.2'],['S3','I3.3'],['S4','I3.4'],['S5','I3.5'],['S6','I3.6'],['K10','Q5.2']],'الرمز','العنوان (مستنتج)')},
  {html:'<p><b>الحل (ص 20):</b> بوابة OR تجمع I3.3 (معكوساً) و I3.5، ثم AND مع I3.4 = الفرع الأول. وبوابة AND تجمع I3.1 و I3.2 = الفرع الثاني. ثم OR تجمع الفرعين، ثم AND مع I3.6 معكوساً ← Q5.2.</p>'},
  {fig:'',ref:'ص 20',caption:'مخطط البوابات المنطقية (FBD) لمثال 2',draw:()=>progFig(C.F2.program,'fbd',C.F2.io)},
  {note:AR_NOTE+'S3 في الشكل (6-2) تلامس <b>مغلق</b>، لذلك يمرر وهو غير مضغوط: يكفي أن تضغط S4 وحده ليعمل K10. إذا ضغطت S3 فلا بد من S5 مع S4.'}
 ],
 steps:[
  {t:'مثال 1: شغّل بـ S1',x:SW_NOTE+' انقر S1. في FBD لاحظ: مدخل OR الأول = 1 ← خرج OR = 1 ← AND = 1 لأن S0 = 0 والدائرة الصغيرة تعكسه إلى 1.',done:s=>(s.variant||'ex1')==='ex1'&&s.Q('Q4.5')},
  {t:'مثال 1: افصل بـ S0',x:'انقر S0: يصبح مدخل AND المعكوس 0 فتنطفئ H1.',done:s=>(s.variant||'ex1')==='ex1'&&s.btn('S0')&&!s.Q('Q4.5')},
  {t:'مثال 2: S4 وحده',x:'اختر «مثال 2» وأرجع المفاتيح. انقر S4 فقط: يعمل K10 لأن S3 المغلق يمرر.',done:s=>s.variant==='ex2'&&s.btn('S4')&&!s.btn('S3')&&s.Q('Q5.2')},
  {t:'مثال 2: اضغط S3',x:'انقر S3 مع بقاء S4: يفصل K10. ثم انقر S5: يعمل مرة أخرى عبر S5.',done:s=>s.variant==='ex2'&&s.btn('S3')&&s.btn('S5')&&s.btn('S4')&&s.Q('Q5.2')},
  {t:'مثال 2: الفرع الآخر',x:'أرجع S3 و S4 و S5، ثم انقر S1 و S2 معاً: يعمل K10 عبر بوابة AND الثانية.',done:s=>s.variant==='ex2'&&s.btn('S1')&&s.btn('S2')&&!s.btn('S4')&&s.Q('Q5.2')},
  {t:'مثال 2: الفصل بـ S6',x:'انقر S6: يفصل K10 مهما كان الفرع الذي يغذيه.',done:s=>s.variant==='ex2'&&s.btn('S6')&&!s.Q('Q5.2')}
 ],
 quiz:[
  {q:'بوابة AND تكافئ توصيل المفاتيح على:',o:['التوازي','التوالي','مفتاح مغلق','لا تكافئ شيئاً'],c:1,e:'«تكافئ توصيل مفتاحين على التوالي» ص 17.'},
  {q:'ما رمز بوابة OR في FBD؟',o:['&','>=1','=','N'],c:1,e:'مستطيل بداخله ‎>=1‎.'},
  {q:'أقصى عدد مداخل لبوابة AND حسب الكتاب:',o:['2','4','8','16'],c:2,e:'«أقصى عدد مداخل لبوابة (AND) هو (8) مداخل».'},
  {q:'بوابة NOT تمثل:',o:['مفتاحاً مفتوحاً N.O.','مفتاحاً مغلقاً N.C.','مفتاحين على التوازي','الحمل'],c:1,e:'«وهي تمثل مفتاحاً مغلقاً (N.C)».'},
  {q:'بوابة OR بمدخلين قيمتهما 0 و 1. الخرج:',o:['0','1','غير معروف','2'],c:1,e:'يكفي أن يكون أحد المداخل 1.'},
  {q:'في مثال 1، لماذا يدخل I0.0 إلى AND بدائرة صغيرة؟',o:['لأنه ضاغط فصل يجب أن يقطع عندما يصبح 1','لأنه ضاغط تشغيل','لأنه الخرج','لتسريع البرنامج'],c:0,e:'الدائرة الصغيرة = NOT، أي تلامس مغلق.'},
  {q:'في مثال 2 (الشكل 6-2)، أي ضغطة وحدها تشغّل K10؟',o:['S1','S5','S4','S6'],c:2,e:'S3 مغلق يمرر، فيكفي S4، و S6 غير مضغوط.'},
  {q:'ما الذي ينقص مثال 2 في الكتاب؟',o:['الحل FBD','دائرة مسار التيار','الدراسة وجدول الترميز','رقم الشكل'],c:2,e:'الحل يستعمل I3.x و Q5.2 بلا جدول ترميز.'}
 ]
},{ex1:C.F1,ex2:C.F2},'ex1','اختر المثال: مثال 1 (الشكل 5-2) أو مثال 2 (الشكل 6-2).');

